package org.eclipse.jdt.ui.text.java;

import org.eclipse.jdt.core.CompletionProposal;
import org.eclipse.jface.resource.ImageDescriptor;
import org.eclipse.jdt.internal.ui.JavaPlugin;
import org.eclipse.jdt.internal.ui.JavaPluginImages;
import org.eclipse.ui.ide.IDE;

public class CompletionProposalLabelProvider {
    // Assuming JavaPlugin.getDefault() is accessible in a real context
    // and other imports are managed by the environment.

    public ImageDescriptor getImageDescriptor(CompletionProposal proposal) {
        switch (proposal.getKind()) {
            case CompletionProposal.MODULE_REF:
                // Bug: Using generic project icon for module reference
                return JavaPlugin.getDefault().getWorkbench().getSharedImages().getImageDescriptor(IDE.SharedImages.IMG_OBJ_PROJECT);
            default:
                return JavaPluginImages.DESC_OBJS_CLASS;
        }
    }
}

afterExample:
package org.eclipse.jdt.ui.text.java;

import org.eclipse.jdt.core.CompletionProposal;
import org.eclipse.jface.resource.ImageDescriptor;
import org.eclipse.jdt.internal.ui.JavaPluginImages;

public class CompletionProposalLabelProvider {
    // Assuming JavaPlugin.getDefault() is accessible in a real context.

    public ImageDescriptor getImageDescriptor(CompletionProposal proposal) {
        switch (proposal.getKind()) {
            case CompletionProposal.MODULE_REF:
                // Fix: Using specific module icon for module reference
                return JavaPluginImages.DESC_OBJS_MODULE;
            default:
                return JavaPluginImages.DESC_OBJS_CLASS;
        }
    }
}

